class GameObjects {
    _step;
    _player;
    _history; //TODO 
    constructor(step, player, history = 'todo') {
        this._step = step;
        this._player = player;
        this._history = history;
    }
    getStep() {
        return this._step;
    }
    getPlayer() {
        return this._player;
    }
    getHistory() {
        return this._history;
    }
}
export default GameObjects;
