class Observer {
    _subscrubers;
    constructor() {
        this._subscrubers = [];
    }
    addSubscrubir(s) {
        this._subscrubers.push(s);
    }
    updated() {
        for (let i = 0; i < this._subscrubers.length; i++) {
            this._subscrubers[i].update();
        }
    }
}
export default Observer;
